async function pool(items,limit,worker){let next=0;await Promise.all(Array.from({length:Math.min(limit,items.length)},async()=>{while(next<items.length){const item=items[next++];await worker(item)}}))}
function scheduleRender(){if(renderTimer)return;renderTimer=setTimeout(()=>{renderTimer=0;if(visible)render()},250)}
try{if(window.Native){const raw=JSON.parse(Native.state());if(raw.version)state=Core.validateState(raw);quotes=JSON.parse(Native.cachedQuotes())}}catch(e){console.warn('Saved state failed validation',e)}
function ensureHeldInWatch(){let added=false;for(const h of state.holdings)if(!state.watch.some(w=>w.symbol===h.symbol)){state.watch.push({symbol:h.symbol,name:h.name,currency:h.currency,type:h.type||'EQUITY'});added=true}return added}
state.watch=state.watch.filter(x=>!blockedWatch.includes(x.symbol));
