function rpc(action,payload={}){if(!window.Native)return Promise.reject(Error('앱에서 연결할 수 있습니다'));const id=String(++sequence);return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(Error('연결 시간 초과'))},90000);pending.set(id,{resolve,reject,timer});Native.request(id,action,JSON.stringify(payload))})}
