const money=(n,currency='KRW')=>Core.finite(n)?(currency==='USD'?'$':'')+n.toLocaleString('ko-KR',{minimumFractionDigits:currency==='USD'||currency==='POINTS'?2:0,maximumFractionDigits:currency==='USD'||currency==='POINTS'?2:0})+(currency==='KRW'?'원':currency==='POINTS'?' pt':''):'—';
